export const getSetMemberRoleUrl = (key: string, accountId: string) => {
  return `/v1/access/points/${key}/members/${accountId}`;
};

/**
 * Sets the exact role of a member, up or down. Needs Administrator; Owner to set or change Owner.
 */
export const setMemberRole = async (
  key: string,
  accountId: string,
  memberRoleUpdate?: MemberRoleUpdate,
  options?: Parameters<typeof storytellerFetch>[1],
): Promise<AccessPointMember> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return storytellerFetch<AccessPointMember>(
    getSetMemberRoleUrl(key, accountId),
    {
      ...options,
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(memberRoleUpdate),
    },
  );
};

